function policyMetadata(scope){return Object.entries(scope==='public'?publicPolicy:privatePolicy).map(([key,value])=>{let min=1,max=value;const interval=['operatorIntervalMs','ipIntervalMs','roomWindowMs','admissionWindowMs'].includes(key);if(scope==='public'){if(interval){min=value;max=3600000}if(['leaseMs','grantMs'].includes(key)){min=1000;max=300000}if(key==='batchMs'){min=2000;max=10000}}else{if(key==='readCadenceMs'){min=2000;max=10000}if(key==='handlers')max=160;if(key==='bodyInflight')max=16}if(key==='responseBytes')min=max=65536;return {path:scope+'.policy.'+key,label:names[key]||key,key,min,max,unit:key.endsWith('Ms')?'ms':(scope==='public'?key.toLowerCase().includes('bytes'):key.endsWith('Bytes'))?'bytes':'count',applyTo:scope==='public'?'runtime':'new_room',readOnly:min===max}})}
const get=(v,path)=>path.split('.').reduce((o,k)=>o?.[k],v);
